{"file_path":"src/address.js","content":"/**
 * Cell address helpers: validation, column/number conversion, and range
 * expansion. An address is one or two letters (A..ZZ) followed by one to
 * three digits naming a row of at least 1.
 */

const ADDRESS_RE = /^([A-Z]{1,2})(\d{1,3})$/

/** Convert column letters (A..ZZ) to a 1-based column number. */
export function colToNum(letters) {
  let n = 0
  for (const ch of letters) n = n * 26 + (ch.charCodeAt(0) - 64)
  return n
}

/** Convert a 1-based column number back to letters. */
export function numToCol(n) {
  let s = ''
  while (n > 0) {
    const rem = (n - 1) % 26
    s = String.fromCharCode(65 + rem) + s
    n = Math.floor((n - 1) / 26)
  }
  return s
}

/** True when `word` is an address inside the addressable range. */
export function isValidAddress(word) {
  const m = ADDRESS_RE.exec(word)
  if (!m) return false
  return parseInt(m[2], 10) >= 1
}

/** Parse an in-range address into `{ col, row }`, or null when out of range. */
export function parseAddress(word) {
  const m = ADDRESS_RE.exec(word)
  if (!m) return null
  const row = parseInt(m[2], 10)
  if (row < 1) return null
  return { col: colToNum(m[1]), row }
}

export function addressString(col, row) {
  return numToCol(col) + String(row)
}

/** Compare two `{ col, row }` positions: ascending column, then row. */
export function compareAddresses(a, b) {
  if (a.col !== b.col) return a.col - b.col
  return a.row - b.row
}

/**
 * Expand a range given by its two corner address words (in either order)
 * into address strings in ascending column, then row, order. Returns null
 * when either corner is outside the addressable range.
 */
export function expandRange(fromWord, toWord) {
  const a = parseAddress(fromWord)
  const b = parseAddress(toWord)
  if (!a || !b) return null
  const colMin = Math.min(a.col, b.col)
  const colMax = Math.max(a.col, b.col)
  const rowMin = Math.min(a.row, b.row)
  const rowMax = Math.max(a.row, b.row)
  const result = []
  for (let c = colMin; c <= colMax; c++) {
    for (let r = rowMin; r <= rowMax; r++) {
      result.push(addressString(c, r))
    }
  }
  return result
}
"}

