{"file_path":"src/sheet.js","content":"/**
 * Parse a sheet from raw standard input text into a map of address to
 * declared cell content, per the line format in the task specification.
 */

import { isValidAddress } from './address.js'

export class SheetError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i].replace(/^[ \t]+/, '')
    if (line === '' || line.startsWith('#')) continue

    const addrMatch = /^[^ \t]+/.exec(line)
    const addrRaw = addrMatch[0]
    const rest = line.slice(addrRaw.length).replace(/^[ \t]+/, '')
    const addr = addrRaw.toUpperCase()

    if (!isValidAddress(addr)) {
      throw new SheetError(lineNo, `invalid cell address ${addr}`)
    }
    if (cells.has(addr)) {
      throw new SheetError(lineNo, `cell ${addr} is declared twice`)
    }
    cells.set(addr, rest)
  }
  return cells
}
"}

