{"file_path":"src/tokenizer.js","content":"/**
 * Tokenizer for formula bodies (the text after a leading `=`).
 */

export class LexError extends Error {}

// Order matters: longer operator spellings must be tried before their
// single-character prefixes.
const SPECS = [
  { type: 'WS', re: /^[ \t]+/ },
  { type: 'NUMBER', re: /^\d+(\.\d+)?/ },
  { type: 'NAME', re: /^[A-Za-z]+\d*/ },
  { type: 'LE', re: /^<=/ },
  { type: 'GE', re: /^>=/ },
  { type: 'NE', re: /^<>/ },
  { type: 'LT', re: /^</ },
  { type: 'GT', re: /^>/ },
  { type: 'EQ', re: /^=/ },
  { type: 'PLUS', re: /^\+/ },
  { type: 'MINUS', re: /^-/ },
  { type: 'STAR', re: /^\*/ },
  { type: 'SLASH', re: /^\// },
  { type: 'CARET', re: /^\^/ },
  { type: 'LPAREN', re: /^\(/ },
  { type: 'RPAREN', re: /^\)/ },
  { type: 'COMMA', re: /^,/ },
  { type: 'COLON', re: /^:/ },
]

export function tokenize(text) {
  const tokens = []
  let pos = 0
  while (pos < text.length) {
    const chunk = text.slice(pos)
    let matched = null
    for (const spec of SPECS) {
      const m = spec.re.exec(chunk)
      if (m) {
        matched = { type: spec.type, text: m[0] }
        break
      }
    }
    if (!matched) throw new LexError(`unexpected character at ${pos}`)
    pos += matched.text.length
    if (matched.type !== 'WS') tokens.push(matched)
  }
  return tokens
}
"}

