{"file_path":"src/values.js","content":"/**
 * Value representation and the shared arithmetic/comparison semantics used
 * by the formula evaluator: a value is a number, text, a boolean, or an
 * error token.
 */

export function numberValue(v) {
  return { kind: 'number', value: v }
}
export function textValue(v) {
  return { kind: 'text', value: v }
}
export function boolValue(v) {
  return { kind: 'bool', value: v }
}
export function errorValue(token) {
  return { kind: 'error', value: token }
}

export const ERR_DIV0 = errorValue('#DIV/0!')
export const ERR_REF = errorValue('#REF!')
export const ERR_VALUE = errorValue('#VALUE!')
export const ERR_CYCLE = errorValue('#CYCLE!')
export const ERR_NAME = errorValue('#NAME?')
export const ERR_ERR = errorValue('#ERR!')

export const ERROR_TOKENS = new Set([
  '#DIV/0!',
  '#REF!',
  '#VALUE!',
  '#CYCLE!',
  '#NAME?',
  '#ERR!',
])

/** Read a value as a number for arithmetic: booleans convert, text errors. */
export function toNumber(v) {
  if (v.kind === 'error') return v
  if (v.kind === 'number') return v
  if (v.kind === 'bool') return numberValue(v.value ? 1 : 0)
  return ERR_VALUE
}

/** Read a value as a boolean condition: booleans and numbers convert. */
export function toBoolean(v) {
  if (v.kind === 'error') return v
  if (v.kind === 'bool') return v
  if (v.kind === 'number') return boolValue(v.value !== 0)
  return ERR_VALUE
}

function finiteOrDiv0(n) {
  return Number.isFinite(n) ? numberValue(n) : ERR_DIV0
}

/** Apply an arithmetic operator to two already-numeric operands. */
export function arithmetic(op, a, b) {
  switch (op) {
    case '+':
      return finiteOrDiv0(a + b)
    case '-':
      return finiteOrDiv0(a - b)
    case '*':
      return finiteOrDiv0(a * b)
    case '/':
      if (b === 0) return ERR_DIV0
      return finiteOrDiv0(a / b)
    case '^':
      return finiteOrDiv0(Math.pow(a, b))
    default:
      throw new Error(`unknown arithmetic operator ${op}`)
  }
}

const KIND_RANK = { number: 0, text: 1, bool: 2 }

/** Compare two non-error values per the cross-kind ordering rules. */
export function compareValues(op, l, r) {
  let cmp
  if (l.kind === r.kind) {
    if (l.kind === 'number' || l.kind === 'text') {
      cmp = l.value < r.value ? -1 : l.value > r.value ? 1 : 0
    } else {
      cmp = l.value === r.value ? 0 : l.value ? 1 : -1
    }
  } else {
    cmp = KIND_RANK[l.kind] - KIND_RANK[r.kind]
  }
  let result
  switch (op) {
    case '=':
      result = cmp === 0
      break
    case '<>':
      result = cmp !== 0
      break
    case '<':
      result = cmp < 0
      break
    case '<=':
      result = cmp <= 0
      break
    case '>':
      result = cmp > 0
      break
    case '>=':
      result = cmp >= 0
      break
    default:
      throw new Error(`unknown comparison operator ${op}`)
  }
  return boolValue(result)
}

/** Round to ten significant digits and print as JavaScript would. */
export function formatNumber(n) {
  if (n === 0) return '0'
  let rounded = Number(n.toPrecision(10))
  if (Object.is(rounded, -0)) rounded = 0
  return String(rounded)
}

export function formatValue(v) {
  switch (v.kind) {
    case 'number':
      return formatNumber(v.value)
    case 'bool':
      return v.value ? 'TRUE' : 'FALSE'
    case 'error':
      return v.value
    case 'text':
      return v.value
    default:
      throw new Error(`unknown value kind ${v.kind}`)
  }
}
"}

