 * (loosest to tightest precedence): comparisons, then `+`/`-`, then `*`/`/`,
 * then `^` (right-associative), then a leading unary `+`/`-` (which binds
 * tighter than `^`). A range (`A1:B3`) is only accepted directly as a
 * function argument.
 */

import { tokenize, LexError } from './tokenizer.js'

export class ParseError extends Error {}

const COMPARISON_TYPES = new Set(['EQ', 'NE', 'LT', 'LE', 'GT', 'GE'])
const COMPARISON_TEXT = { EQ: '=', NE: '<>', LT: '<', LE: '<=', GT: '>', GE: '>=' }

class TokenStream {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }
  peek() {
    return this.tokens[this.pos] ?? null
  }
  next() {
    return this.tokens[this.pos++]
  }
  atEnd() {
    return this.pos >= this.tokens.length
  }
}

/** Parse a formula body (text after the leading `=`). Throws ParseError. */
export function parseFormula(body) {
  let tokens
  try {
    tokens = tokenize(body)
  } catch (e) {
    if (e instanceof LexError) throw new ParseError(e.message)
    throw e
  }
  if (tokens.length === 0) throw new ParseError('empty formula')
  const ts = new TokenStream(tokens)
  const node = parseComparison(ts)
  if (!ts.atEnd()) throw new ParseError('unexpected trailing tokens')
  return node
}

function parseComparison(ts) {
  let left = parseAdditive(ts)
  while (ts.peek() && COMPARISON_TYPES.has(ts.peek().type)) {
    const op = COMPARISON_TEXT[ts.next().type]
    const right = parseAdditive(ts)
    left = { type: 'binop', op, left, right }
  }
  return left
}

function parseAdditive(ts) {
  let left = parseMultiplicative(ts)
  while (ts.peek() && (ts.peek().type === 'PLUS' || ts.peek().type === 'MINUS')) {
    const op = ts.next().type === 'PLUS' ? '+' : '-'
    const right = parseMultiplicative(ts)
    left = { type: 'binop', op, left, right }
  }
  return left
}

function parseMultiplicative(ts) {
  let left = parsePower(ts)
  while (ts.peek() && (ts.peek().type === 'STAR' || ts.peek().type === 'SLASH')) {
    const op = ts.next().type === 'STAR' ? '*' : '/'
    const right = parsePower(ts)
    left = { type: 'binop', op, left, right }
  }
  return left
}

function parsePower(ts) {
  const left = parseUnary(ts)
  if (ts.peek() && ts.peek().type === 'CARET') {
    ts.next()
    const right = parsePower(ts)
    return { type: 'binop', op: '^', left, right }
  }
  return left
}

function parseUnary(ts) {
  const tok = ts.peek()
  if (tok && (tok.type === 'PLUS' || tok.type === 'MINUS')) {
    ts.next()
    const expr = parseUnary(ts)
    return { type: 'unary', op: tok.type === 'PLUS' ? '+' : '-', expr }
  }
  return parsePrimary(ts)
}

function parsePrimary(ts) {
  const tok = ts.peek()
  if (!tok) throw new ParseError('unexpected end of formula')

  if (tok.type === 'NUMBER') {
    ts.next()
    return { type: 'num', value: parseFloat(tok.text) }
  }

  if (tok.type === 'LPAREN') {
    ts.next()
    const inner = parseComparison(ts)
    expect(ts, 'RPAREN')
    return inner
  }

  if (tok.type === 'NAME') {
    ts.next()
    const upper = tok.text.toUpperCase()
    if (upper === 'TRUE' || upper === 'FALSE') {
      return { type: 'bool', value: upper === 'TRUE' }
    }
    if (ts.peek() && ts.peek().type === 'LPAREN') {
      ts.next()
      const args = parseArgList(ts)
      expect(ts, 'RPAREN')
      return { type: 'call', name: upper, args }
    }
    return { type: 'ref', address: upper }
  }

  throw new ParseError(`unexpected token ${tok.type}`)
}

