  const args = []
  if (ts.peek() && ts.peek().type === 'RPAREN') return args
  args.push(parseArgument(ts))
  while (ts.peek() && ts.peek().type === 'COMMA') {
    ts.next()
    args.push(parseArgument(ts))
  }
  return args
}

