  const t0 = ts.tokens[ts.pos]
  const t1 = ts.tokens[ts.pos + 1]
  const t2 = ts.tokens[ts.pos + 2]
  if (t0 && t0.type === 'NAME' && t1 && t1.type === 'COLON' && t2 && t2.type === 'NAME') {
    ts.pos += 3
    return { type: 'range', from: t0.text.toUpperCase(), to: t2.text.toUpperCase() }
  }
  return parseComparison(ts)
}

