const COMPARISON_TEXT = { EQ: '=', NE: '<>', LT: '<', LE: '<=', GT: '>', GE: '>=' }

class TokenStream {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }
  peek() {
    return this.tokens[this.pos] ?? null
  }
  next() {
    return this.tokens[this.pos++]
  }
  atEnd() {
    return this.pos >= this.tokens.length
  }
