 * Evaluates cell contents: literals directly, formulas by walking the AST
 * produced by the parser. Handles memoization, cycle detection, and the
 * built-in functions.
 */

import { parseFormula, ParseError } from './parser.js'
import { expandRange, isValidAddress } from './address.js'
import {
  numberValue,
  textValue,
  boolValue,
  errorValue,
  ERR_DIV0,
  ERR_REF,
  ERR_VALUE,
  ERR_CYCLE,
  ERR_NAME,
  ERR_ERR,
  ERROR_TOKENS,
  toNumber,
  toBoolean,
  arithmetic,
  compareValues,
} from './values.js'

const NUMERIC_LITERAL_RE = /^-?\d+(\.\d+)?$/
const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const VARIADIC_FUNCTIONS = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'])

function parseLiteral(content) {
  if (content === '') return numberValue(0)
  if (ERROR_TOKENS.has(content)) return errorValue(content)
  if (NUMERIC_LITERAL_RE.test(content)) return numberValue(parseFloat(content))
  return textValue(content)
}

/** Value {kind:'error'} for a text operand, else null. */
function arithProblem(v) {
  if (v.kind === 'error') return v
  if (v.kind === 'text') return ERR_VALUE
  return null
}

export class Evaluator {
  constructor(cells) {
    this.cells = cells // Map address -> declared content string
    this.parsed = new Map() // address -> ast | null (null means grammar failure)
    this.values = new Map() // address -> Value
    this.visiting = new Set()
  }

  getAst(addr) {
    if (this.parsed.has(addr)) return this.parsed.get(addr)
    const content = this.cells.get(addr) ?? ''
    let ast = null
    if (content.startsWith('=')) {
      try {
        ast = parseFormula(content.slice(1))
      } catch (e) {
        if (!(e instanceof ParseError)) throw e
      }
    }
    this.parsed.set(addr, ast)
    return ast
  }

  evaluateCell(addr) {
    if (this.values.has(addr)) return this.values.get(addr)
    if (this.visiting.has(addr)) {
      this.values.set(addr, ERR_CYCLE)
      return ERR_CYCLE
    }
    this.visiting.add(addr)
    const content = this.cells.get(addr) ?? ''
    let result
    if (content.startsWith('=')) {
      const ast = this.getAst(addr)
      result = ast === null ? ERR_ERR : evaluate(ast, this)
    } else {
      result = parseLiteral(content)
    }
    this.visiting.delete(addr)
    this.values.set(addr, result)
    return result
  }
}

function evaluate(node, ctx) {
  switch (node.type) {
    case 'num':
      return numberValue(node.value)
    case 'bool':
      return boolValue(node.value)
    case 'ref':
      return isValidAddress(node.address) ? ctx.evaluateCell(node.address) : ERR_REF
    case 'range':
