  const items = []
  for (const node of argNodes) {
    if (node.type === 'range') {
      const cells = expandRange(node.from, node.to)
      if (cells === null) {
        items.push(ERR_REF)
      } else {
        for (const a of cells) items.push(ctx.evaluateCell(a))
      }
    } else {
      items.push(evaluate(node, ctx))
    }
  }
  return items
