    for (const v of items) {
      if (v.kind === 'error') return v
    }
    return numberValue(items.filter((v) => v.kind === 'number').length)
  }

  const nums = []
  for (const v of items) {
    if (v.kind === 'error') return v
    const n = toNumber(v)
    if (n.kind === 'error') return n
    nums.push(n.value)
  }

  let r
  switch (name) {
    case 'SUM':
      r = nums.reduce((a, b) => a + b, 0)
      break
    case 'MIN':
      r = Math.min(...nums)
      break
    case 'MAX':
      r = Math.max(...nums)
      break
    case 'AVG':
      r = nums.reduce((a, b) => a + b, 0) / nums.length
      break
    default:
      throw new Error(`unknown variadic function ${name}`)
  }
  return Number.isFinite(r) ? numberValue(r) : ERR_DIV0
}

function evaluateCall(node, ctx) {
  const { name, args } = node

  if (name === 'IF') {
    if (args.length !== 3) return ERR_ERR
    const condBool = toBoolean(argToScalar(args[0], ctx))
    if (condBool.kind === 'error') return condBool
    return argToScalar(condBool.value ? args[1] : args[2], ctx)
  }

  if (name === 'ABS') {
    if (args.length !== 1) return ERR_ERR
    const n = toNumber(argToScalar(args[0], ctx))
    if (n.kind === 'error') return n
    const r = Math.abs(n.value)
    return Number.isFinite(r) ? numberValue(r) : ERR_DIV0
  }

  if (VARIADIC_FUNCTIONS.has(name)) {
    if (args.length < 1) return ERR_ERR
    return applyVariadic(name, flattenArgs(args, ctx))
  }

  return ERR_NAME
}
