  switch (node.type) {
    case 'num':
      return numberValue(node.value)
    case 'bool':
      return boolValue(node.value)
    case 'ref':
      return isValidAddress(node.address) ? ctx.evaluateCell(node.address) : ERR_REF
    case 'range':
      // The grammar only ever places a range node directly as a function
      // argument, so this position is never actually reached.
