  }
  const lProblem = arithProblem(l)
  if (lProblem) return lProblem
  const rProblem = arithProblem(r)
  if (rProblem) return rProblem
  return arithmetic(node.op, toNumber(l).value, toNumber(r).value)
}

/** Expand a single function argument (range or expression) to one value. */
function argToScalar(node, ctx) {
  if (node.type === 'range') {
    const cells = expandRange(node.from, node.to)
    if (cells === null) return ERR_REF
    for (const a of cells) {
      const v = ctx.evaluateCell(a)
      if (v.kind === 'error') return v
    }
    return ctx.evaluateCell(cells[0])
  }
  return evaluate(node, ctx)
