{"file_path":"src/deps.js","content":"/**
 * Collects the cells a formula names directly (ranges expanded), for the
 * `deps` output mode.
 */

import { expandRange, isValidAddress, parseAddress, compareAddresses } from './address.js'

function collect(node, set) {
  switch (node.type) {
    case 'num':
    case 'bool':
      return
    case 'ref':
      if (isValidAddress(node.address)) set.add(node.address)
      return
    case 'range': {
      const cells = expandRange(node.from, node.to)
      if (cells) for (const a of cells) set.add(a)
      return
    }
    case 'unary':
      collect(node.expr, set)
      return
    case 'binop':
      collect(node.left, set)
      collect(node.right, set)
      return
    case 'call':
      for (const arg of node.args) collect(arg, set)
      return
    default:
      throw new Error(`unknown node type ${node.type}`)
  }
}

/** Returns the distinct addresses a cell's formula names, sorted by column then row. */
export function computeDeps(ast) {
  if (ast === null) return []
  const set = new Set()
  collect(ast, set)
  return [...set].sort((a, b) => compareAddresses(parseAddress(a), parseAddress(b)))
}
"}

