{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { readFileSync } from 'node:fs'
import { parseSheet, SheetError } from './sheet.js'
import { Evaluator } from './evaluator.js'
import { computeDeps } from './deps.js'
import { formatValue } from './values.js'
import { parseAddress, compareAddresses } from './address.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (mode !== 'values' && mode !== 'deps') {
    fail('usage: cli.js values|deps')
  }

  const input = readFileSync(0, 'utf8')

  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) fail(`line ${e.line}: ${e.message}`)
    throw e
  }

  const addresses = [...cells.keys()].sort((a, b) =>
    compareAddresses(parseAddress(a), parseAddress(b))
  )

  const lines = []
  if (mode === 'values') {
    const evaluator = new Evaluator(cells)
    for (const addr of addresses) {
      lines.push(`${addr}=${formatValue(evaluator.evaluateCell(addr))}`)
    }
  } else {
    const evaluator = new Evaluator(cells)
    for (const addr of addresses) {
      const deps = computeDeps(evaluator.getAst(addr))
      lines.push(`${addr}: ${deps.join(' ')}`.replace(/: $/, ':'))
    }
  }

  process.stdout.write(lines.map((l) => l + '\n').join(''))
}

main()
"}

