      lines.push(`${addr}=${formatValue(evaluator.evaluateCell(addr))}`)
    }
  } else {
    const evaluator = new Evaluator(cells)
    for (const addr of addresses) {
      const deps = computeDeps(evaluator.getAst(addr))
      lines.push(`${addr}: ${deps.join(' ')}`.replace(/: $/, ':'))
    }
  }

  process.stdout.write(lines.map((l) => l + '\n').join(''))
}

